content:
{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको business making machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "Hello क्या आप अभी line पे हैं?"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ बोलिए।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "चलिए अब production capacity के बारे में बात कर लेते हैं।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आपको 100 kilograms per hour चाहिए या कुछ और?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "हाँ सौ kilogram एक घंटा में चाहिए तो उसमें जो है ना जैसे machine हमको है ये है।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अब बताइए motor power में क्या prefer करेंगे?"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "5 ampere hour, 10 ampere hour या कोई और?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "हमारे जो दस दस वो जो है ना Eicher machine है ये 14 HP का है तो इस पर हम चलाना चाह रहे थे कि वो चक्की वही आति वाला hammer वाला।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "ठीक है मैं समझ गई।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "बस एक आखरी detail आप अपनी city और state भी बता दीजिए please।"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आप अपनी city और state बता दीजिए please."
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "हाँ ये Madhepura जिला हुआ।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आप Madhepura Bihar से बोल रहे हैं ना?"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "हाँ हाँ हाँ।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आप अपना नाम भी बता दीजिए please."
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "मेरा नाम है नरेश कुमार यादव।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "नरेश कुमार यादव जी।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "अभी line पे काफी अच्छे seller available हैं।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "आप उनसे अपने हिसाब से price और बाकी details discuss कर लीजिए।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "क्या मैं आपकी बात उनसे करवा दूं?"
    },
    {
      "i": 28,
      "speaker": "caller",
      "text": "अभी।"
    },
    {
      "i": 29,
      "speaker": "caller",
      "text": "हाँ करवाइए ना पूछ लेते हैं कि क्या कीमत पड़ेगा तब वो जानकारी होने के बाद ही ना कुछ करेंगे।"
    }
  ]
}
